                let m = (l + r) / 2;
                if nums[m] > target - nums[i] {
                    r = m;
                } else {
                    l = m + 1;
                }
            }
            let j = l - 1;
            ans = (ans + f[j - i]) % MOD;
        }
        ans
    }
